"""Generate Next.js App Router pages and layouts from the FrontendIR.

Emits:
- Root layout with providers
- Auth layout (centered card)
- Dashboard layout (sidebar shell)
- Landing page (redirect)
- Login / Signup pages
- Dashboard page
- Profile view / edit pages
- Search page
- Profile detail page
- Conversation list / detail pages
- Notification page
- Public registration page
"""

from __future__ import annotations

from ..ir import FrontendIR
from ..naming import slug_to_pascal

_HEADER = """\
// AUTO-GENERATED by Cosolvent Frontend Compiler v{version}
// spec_hash: {hash}
// DO NOT EDIT — changes will be overwritten on next compile
"""


def emit_routes(ir: FrontendIR) -> dict[str, str]:
    files: dict[str, str] = {}

    files["src/app/layout.tsx"] = _root_layout(ir)
    files["src/app/page.tsx"] = _landing_page(ir)

    files["src/app/(auth)/layout.tsx"] = _auth_layout(ir)
    files["src/app/(auth)/login/page.tsx"] = _login_page(ir)

    page_ids = {p.id for p in ir.pages}

    if "signup" in page_ids:
        files["src/app/(auth)/signup/page.tsx"] = _signup_page(ir)

    files["src/app/(dashboard)/layout.tsx"] = _dashboard_layout(ir)
    files["src/app/(dashboard)/page.tsx"] = _dashboard_page(ir)

    files["src/app/(dashboard)/profile/page.tsx"] = _profile_view_page(ir)
    files["src/app/(dashboard)/profile/edit/page.tsx"] = _profile_edit_page(ir)

    if "search" in page_ids:
        files["src/app/(dashboard)/search/page.tsx"] = _search_page(ir)

    files["src/app/(dashboard)/profiles/[id]/page.tsx"] = _profile_detail_page(ir)

    if "conversations" in page_ids:
        files["src/app/(dashboard)/conversations/page.tsx"] = _conversations_page(ir)
        files["src/app/(dashboard)/conversations/[id]/page.tsx"] = (
            _conversation_detail_page(ir)
        )

    if "notifications" in page_ids:
        files["src/app/(dashboard)/notifications/page.tsx"] = _notifications_page(ir)

    if "register" in page_ids:
        files["src/app/register/[type]/page.tsx"] = _register_page(ir)

    files["src/lib/providers.tsx"] = _providers(ir)

    return files


# ── Root layout ───────────────────────────────────────────────────────


def _root_layout(ir: FrontendIR) -> str:
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
import type {{ Metadata }} from "next";
import {{ Inter }} from "next/font/google";
import "@/styles/globals.css";
import {{ Providers }} from "@/lib/providers";

const inter = Inter({{ subsets: ["latin"] }});

export const metadata: Metadata = {{
  title: "{ir.marketplace.name}",
  description: "{ir.marketplace.description}",
}};

export default function RootLayout({{
  children,
}}: {{
  children: React.ReactNode;
}}) {{
  return (
    <html lang="en" suppressHydrationWarning>
      <body className={{inter.className}}>
        <Providers>{{children}}</Providers>
      </body>
    </html>
  );
}}
"""


def _providers(ir: FrontendIR) -> str:
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ QueryClient, QueryClientProvider }} from "@tanstack/react-query";
import {{ useState }} from "react";

export function Providers({{ children }}: {{ children: React.ReactNode }}) {{
  const [queryClient] = useState(
    () =>
      new QueryClient({{
        defaultOptions: {{
          queries: {{
            staleTime: 60 * 1000,
            retry: 1,
          }},
        }},
      }}),
  );

  return (
    <QueryClientProvider client={{queryClient}}>
      {{children}}
    </QueryClientProvider>
  );
}}
"""


