def _landing_page(ir: FrontendIR) -> str:
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
import {{ redirect }} from "next/navigation";

export default function LandingPage() {{
  redirect("/login");
}}
"""


def _login_page(ir: FrontendIR) -> str:
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ useState }} from "react";
import {{ useRouter }} from "next/navigation";
import {{ Button }} from "@/components/ui/button";
import {{ Input }} from "@/components/ui/input";
import {{ Label }} from "@/components/ui/label";
import {{ Card, CardContent, CardDescription, CardHeader, CardTitle }} from "@/components/ui/card";
import * as authApi from "@/generated/api/auth";

export default function LoginPage() {{
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: React.FormEvent) {{
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {{
      await authApi.login_api_auth_login_post({{ email, password }});
      router.push("/profile");
    }} catch (err: unknown) {{
      setError(err instanceof Error ? err.message : "Login failed");
    }} finally {{
      setLoading(false);
    }}
  }}

  return (
    <Card>
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">{ir.marketplace.name}</CardTitle>
        <CardDescription>Sign in to your account</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={{handleSubmit}} className="space-y-4">
          {{error && (
            <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
              {{error}}
            </div>
          )}}
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              value={{email}}
              onChange={{(e) => setEmail(e.target.value)}}
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              value={{password}}
              onChange={{(e) => setPassword(e.target.value)}}
              required
            />
          </div>
          <Button type="submit" className="w-full" disabled={{loading}}>
            {{loading ? "Signing in..." : "Sign In"}}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}}
"""


def _signup_page(ir: FrontendIR) -> str:
    type_options = "\n".join(
        f'            <option value="{e.slug}">{e.name}</option>'
        for e in ir.entities
    )
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ useState }} from "react";
import {{ useRouter }} from "next/navigation";
import {{ Button }} from "@/components/ui/button";
import {{ Input }} from "@/components/ui/input";
import {{ Label }} from "@/components/ui/label";
import {{ Card, CardContent, CardDescription, CardHeader, CardTitle }} from "@/components/ui/card";
import * as authApi from "@/generated/api/auth";

export default function SignupPage() {{
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [participantType, setParticipantType] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: React.FormEvent) {{
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {{
      await authApi.signup_api_auth_signup_post({{
        email,
        password,
        participant_type: participantType,
      }});
      router.push("/profile");
    }} catch (err: unknown) {{
      setError(err instanceof Error ? err.message : "Signup failed");
    }} finally {{
      setLoading(false);
    }}
  }}

  return (
    <Card>
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">Create Account</CardTitle>
        <CardDescription>Join {ir.marketplace.name}</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={{handleSubmit}} className="space-y-4">
          {{error && (
            <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
              {{error}}
            </div>
          )}}
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              value={{email}}
              onChange={{(e) => setEmail(e.target.value)}}
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              value={{password}}
              onChange={{(e) => setPassword(e.target.value)}}
              required
              minLength={{8}}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="type">I am a...</Label>
            <select
              id="type"
              className="w-full rounded-md border border-input bg-background px-3 py-2"
              value={{participantType}}
              onChange={{(e) => setParticipantType(e.target.value)}}
              required
            >
              <option value="">Select type</option>
{type_options}
            </select>
          </div>
          <Button type="submit" className="w-full" disabled={{loading}}>
            {{loading ? "Creating account..." : "Create Account"}}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}}
"""


